# --- shared I/O helpers -----------------------------------------------------


def _read_json_file(path) -> tuple[Optional[object], Optional[str]]:
    """Read + parse a JSON file. Returns (data, None) on success or
    (None, error_message) on any IO or parse failure -- never raises.
    """
    try:
        text = Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        return None, f"cannot read {path}: {exc}"
    try:
        return json.loads(text), None
    except json.JSONDecodeError as exc:
        return None, f"invalid JSON in {path}: {exc}"


def _load_citation_guard() -> types.ModuleType:
    """Dynamically load citation-guard.py (hyphenated filename, so it can't
    be `import`ed normally) so citation-floor can REUSE its citation/
    footnote span regexes rather than reinventing them (see module
    docstring). Raises ImportError if the sibling script is missing --
    callers treat that as an exit-2 "could not run" condition.
    """
    if not CITATION_GUARD_PATH.is_file():
        raise ImportError(f"citation-guard.py not found at {CITATION_GUARD_PATH}")
    spec = importlib.util.spec_from_file_location("academic_helper_citation_guard", CITATION_GUARD_PATH)
    if spec is None or spec.loader is None:
        raise ImportError(f"could not load spec for {CITATION_GUARD_PATH}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


# --- result / output helpers ------------------------------------------------


def _make_result(gate: str, status: str, detail: str, violations: list) -> dict:
    return {"gate": gate, "status": status, "detail": detail, "violations": violations}


def _print_result(result: dict, json_mode: bool) -> None:
    if json_mode:
        print(json.dumps(result, ensure_ascii=False))
        return
    print(f"gate {result['gate']}: {result['status'].upper()} -- {result['detail']}")
    violations = result.get("violations") or []
    if result["status"] != "pass" and violations:
        shown = violations[:10]
        for v in shown:
            if isinstance(v, dict):
                bits = ", ".join(f"{k}={v2}" for k, v2 in v.items())
            else:
                bits = str(v)
            print(f"  - {bits}")
        extra = len(violations) - len(shown)
        if extra > 0:
            print(f"  ... and {extra} more")


# --- ledger (session-state.json) side effect --------------------------------


def resolve_ledger_path(explicit: Optional[str]) -> Path:
    if explicit:
        return Path(explicit)
    project_dir = os.environ.get("CLAUDE_PROJECT_DIR")
    if project_dir:
        return Path(project_dir) / ".academic-helper" / "session-state.json"
    return Path(".academic-helper") / "session-state.json"


def merge_ledger(ledger_path: Path, gate_name: str, result: dict) -> None:
    """Best-effort side effect: merge `result` into `ledger_path` under
    gates.<gate_name>. NEVER raises and NEVER changes the caller's exit
    code -- see module docstring. NEVER creates the parent
    `.academic-helper/` directory (CLAUDE.md anti-pattern rule); skips
    silently if it is absent.
    """
    try:
        parent = ledger_path.parent
        if not parent.is_dir():
            return

        existing: dict = {}
        if ledger_path.exists():
            try:
                loaded = json.loads(ledger_path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    existing = loaded
            except (OSError, json.JSONDecodeError):
                existing = {}

        gates = existing.get("gates")
        if not isinstance(gates, dict):
            gates = {}
        gates[gate_name] = {
            "status": result["status"],
            "at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
            "detail": result["detail"],
            "violations": result["violations"],
        }
        existing["gates"] = gates

        fd, tmp_name = tempfile.mkstemp(prefix=".gate-ledger-", dir=str(parent))
        tmp_path = Path(tmp_name)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(existing, fh, ensure_ascii=False, indent=2)
            os.replace(tmp_path, ledger_path)
        except Exception:
            try:
                tmp_path.unlink()
            except OSError:
                pass
            raise
    except Exception:
        # Ledger write is a side effect, not the verdict -- swallow anything.
        return


# --- subcommand: argument-graph ---------------------------------------------


def flatten_outline_units(outline: dict) -> list:
    """Mirror src/workflows/write-sections.js's `flattenUnits()`: a top-level
    `units` array (if present and non-empty) short-circuits everything else.
    Otherwise walk `sections`; a section with no nested `units` array IS
    itself a node, a section WITH one contributes only its units.
    """
    top_units = outline.get("units")
    if isinstance(top_units, list) and top_units:
        return [u for u in top_units if isinstance(u, dict)]

    sections = outline.get("sections")
    if not isinstance(sections, list):
        return []

    flat = []
    for section in sections:
        if not isinstance(section, dict):
            continue
        nested = section.get("units")
        nested = nested if isinstance(nested, list) else []
        if not nested:
            flat.append(section)
            continue
        for unit in nested:
            if isinstance(unit, dict):
                flat.append(unit)
    return flat


def _detect_cycle(nodes_by_id: dict) -> Optional[list]:
    """White/grey/black DFS over `depends_on`. Returns the cycle path
    (list of node ids, first id repeated at the end) or None. Edges to ids
    absent from `nodes_by_id` are skipped here -- those are reported
    separately as dangling-dependency violations, not cycle participants.
    """
    WHITE, GREY, BLACK = 0, 1, 2
    color = {nid: WHITE for nid in nodes_by_id}
    stack: list = []

    def visit(nid: str) -> Optional[list]:
        color[nid] = GREY
        stack.append(nid)
        deps = nodes_by_id[nid].get("depends_on")
        deps = deps if isinstance(deps, list) else []
        for dep in deps:
            if dep not in nodes_by_id:
                continue
            if color.get(dep) == GREY:
                start = stack.index(dep)
                return stack[start:] + [dep]
            if color.get(dep) == WHITE:
                found = visit(dep)
                if found:
                    return found
        stack.pop()
        color[nid] = BLACK
        return None

    for nid in list(nodes_by_id):
        if color[nid] == WHITE:
            found = visit(nid)
            if found:
                return found
    return None


def _has_own_thesis_link(node: dict) -> bool:
    thesis_link = node.get("thesis_link")
    return isinstance(thesis_link, str) and bool(thesis_link.strip())


def _reaches_thesis_link(nid: str, nodes_by_id: dict, memo: dict, visiting: set) -> bool:
    """True if `nid` has its own `thesis_link`, OR transitively `depends_on`
    a node that does -- the exact walk src/skills/write/SKILL.md:317
    specifies for the "No orphan sections/units" checklist item: "either
    the node has its own `thesis_link` directly, or it `depends_on` a node
    that (transitively) does."

    `visiting` guards against infinite recursion through a `depends_on`
    cycle (cycles are reported separately by `_detect_cycle` -- a node
    whose only path to a thesis_link runs through a cycle that never
    itself reaches one is correctly still orphaned here). `memo` caches
    resolved results across the top-level calls in `check_argument_graph`.
    """
    if nid in memo:
        return memo[nid]
    if nid in visiting:
        return False  # cycle encountered mid-walk -- unresolved through this path

    node = nodes_by_id.get(nid)
    if node is None:
        return False
    if _has_own_thesis_link(node):
        memo[nid] = True
        return True

    visiting.add(nid)
    deps = node.get("depends_on")
    deps = deps if isinstance(deps, list) else []
    result = False
    for dep in deps:
        if dep in nodes_by_id and _reaches_thesis_link(dep, nodes_by_id, memo, visiting):
            result = True
            break
    visiting.discard(nid)
    memo[nid] = result
    return result


def check_argument_graph(outline: dict) -> list:
    nodes = flatten_outline_units(outline)
    nodes_by_id: dict = {}
    positions: dict = {}
    for i, node in enumerate(nodes):
        nid = node.get("id")
        if not isinstance(nid, str) or not nid:
            nid = f"<unnamed-{i}>"
        nodes_by_id[nid] = node
        positions[nid] = i

    violations = []

    # -- dangling-dependency + empty-evidence (per node, local fields only) --
    for nid, node in nodes_by_id.items():
        deps = node.get("depends_on")
        deps = deps if isinstance(deps, list) else []
        for dep in deps:
            if dep not in nodes_by_id:
                violations.append(
                    {
                        "check": "dangling-dependency",
                        "nodeId": nid,
                        "detail": f"depends_on references unknown id '{dep}'",
                    }
                )

        evidence = node.get("evidence")
        if not evidence:
            violations.append(
                {"check": "empty-evidence", "nodeId": nid, "detail": "evidence is missing or empty"}
            )

    # -- No orphan sections/units (SKILL.md:317): transitive thesis_link --
    # reachability over depends_on, not just "does this node have its own".
    memo: dict = {}
    for nid in nodes_by_id:
        if not _reaches_thesis_link(nid, nodes_by_id, memo, set()):
            violations.append(
                {
                    "check": "orphan",
                    "nodeId": nid,
                    "detail": (
                        "no thesis_link on this node, and none reachable by walking its "
                        "depends_on chain (SKILL.md's 'No orphan sections/units' check)"
                    ),
                }
            )

    # -- No circular depends_on references (SKILL.md:318) --
    cycle = _detect_cycle(nodes_by_id)
    if cycle:
        violations.append(
            {
                "check": "cycle",
                "nodeId": cycle[0],
                "detail": "depends_on cycle: " + " -> ".join(cycle),
            }
        )

    # -- Dependency ordering (SKILL.md:320): the flattened outline sequence
    # (the Step 6 writing order) must respect depends_on -- a node cannot
    # appear before every node listed in its depends_on. Positional, over
    # the SAME index a cycle-free graph could still get wrong -- distinct
    # from cycle detection, and tagged with a distinct `check` value so the
    # two stay distinguishable in the output.
    for nid, node in nodes_by_id.items():
        deps = node.get("depends_on")
        deps = deps if isinstance(deps, list) else []
        for dep in deps:
            if dep not in nodes_by_id:
                continue  # already reported as dangling-dependency
            if positions[dep] >= positions[nid]:
                violations.append(
                    {
                        "check": "ordering",
                        "nodeId": nid,
                        "dependsOn": dep,
                        "nodePosition": positions[nid],
                        "dependencyPosition": positions[dep],
                        "detail": (
                            f"'{nid}' is at position {positions[nid]} but its dependency "
                            f"'{dep}' is at position {positions[dep]} -- a dependency must "
                            "come strictly earlier in the writing order"
                        ),
                    }
                )

    return violations


def cmd_argument_graph(args) -> tuple[int, dict]:
    data, err = _read_json_file(args.outline)
    if err:
        return 2, _make_result("argument-graph", "error", err, [])
    if not isinstance(data, dict):
        return 2, _make_result("argument-graph", "error", "outline JSON must be an object", [])

    violations = check_argument_graph(data)
    if violations:
        return 1, _make_result(
            "argument-graph", "fail", f"{len(violations)} violation(s) in argument graph", violations
        )
    return 0, _make_result("argument-graph", "pass", "argument graph valid", [])


# --- subcommand: coverage ----------------------------------------------------

ALLOWED_COVERAGE_STATUSES = {"covered", "skipped-irrelevant"}


def _evidence_id_set(deep_read: dict) -> set:
    evidence = deep_read.get("evidence")
    ids: set = set()
    if isinstance(evidence, list):
        for item in evidence:
            if isinstance(item, dict) and isinstance(item.get("id"), str):
                ids.add(item["id"])
    elif isinstance(evidence, dict):
        ids.update(k for k in evidence.keys())
    return ids


def check_coverage(deep_read: dict) -> list:
    chapter_coverage = deep_read.get("chapter_coverage")
    if not chapter_coverage:
        # Optional field -- absent means nothing to check, matching
        # architect.md:41 ("proceed to thesis proposal as normal").
        return []
    if not isinstance(chapter_coverage, dict):
        raise ValueError("chapter_coverage must be an object keyed by book name")

    evidence_ids = _evidence_id_set(deep_read)
    violations = []

    for book, entries in chapter_coverage.items():
        if not isinstance(entries, list):
            violations.append(
                {"check": "invalid-status", "nodeId": book, "detail": "chapter_coverage entry must be an array"}
            )
            continue

        seen_chapters: list = []
        for entry in entries:
            if not isinstance(entry, dict):
                violations.append(
                    {"check": "invalid-status", "nodeId": book, "detail": "chapter entry must be an object"}
                )
                continue

            chapter = entry.get("chapter")
            node_id = f"{book}:{chapter}"
            status = entry.get("status")

            if status not in ALLOWED_COVERAGE_STATUSES:
                violations.append(
                    {
                        "check": "invalid-status",
                        "nodeId": node_id,
                        "detail": f"status must be one of {sorted(ALLOWED_COVERAGE_STATUSES)}, got {status!r}",
                    }
                )
            elif status == "skipped-irrelevant":
                reason = entry.get("reason")
                if not isinstance(reason, str) or not reason.strip():
                    violations.append(
                        {
                            "check": "invalid-status",
                            "nodeId": node_id,
                            "detail": "skipped-irrelevant requires a non-empty reason",
                        }
                    )

            if isinstance(chapter, int):
                seen_chapters.append(chapter)

            eids = entry.get("evidence_ids")
            if isinstance(eids, list):
                for eid in eids:
                    if eid not in evidence_ids:
                        violations.append(
                            {
                                "check": "dangling-evidence-id",
                                "nodeId": node_id,
                                "detail": f"evidence_ids references unknown id '{eid}'",
                            }
                        )

        if seen_chapters:
            expected = set(range(1, max(seen_chapters) + 1))
            missing = sorted(expected - set(seen_chapters))
            if missing:
                violations.append(
                    {
                        "check": "chapter-gap",
                        "nodeId": book,
                        "detail": f"missing chapter(s) {missing} in contiguous range 1..{max(seen_chapters)}",
                    }
                )

    return violations


def cmd_coverage(args) -> tuple[int, dict]:
    data, err = _read_json_file(args.deep_read)
    if err:
        return 2, _make_result("coverage", "error", err, [])
    if not isinstance(data, dict):
        return 2, _make_result("coverage", "error", "deep-read JSON must be an object", [])

    try:
        violations = check_coverage(data)
    except ValueError as exc:
        return 2, _make_result("coverage", "error", str(exc), [])

    if violations:
        return 1, _make_result(
            "coverage", "fail", f"{len(violations)} violation(s) in chapter coverage", violations
        )
    return 0, _make_result("coverage", "pass", "chapter coverage valid (or not present)", [])


# --- subcommand: citation-floor ---------------------------------------------

_FOOTNOTE_DEF_START_RE = re.compile(r"^\[\^([^\]]+)\]:\s?(.*)$")


def _nfc(text: Optional[str]) -> Optional[str]:
    return unicodedata.normalize("NFC", text) if text else text


def _extract_footnote_defs(text: str) -> dict:
    """id -> definition body text, for every `[^id]: ...` block. Used only
    to look up what a footnote marker actually cites, for classification --
    span *detection* for markers still comes from citation-guard's
    FOOTNOTE_RE (see `classify_citations`).
    """
    lines = text.splitlines()
    defs: dict = {}
    i, n = 0, len(lines)
    while i < n:
        m = _FOOTNOTE_DEF_START_RE.match(lines[i])
        if not m:
            i += 1
            continue
        fid, first = m.group(1), m.group(2)
        body = [first]
        i += 1
        # Stop at a blank line OR the next footnote definition's own start
        # line -- footnote defs are frequently stacked back-to-back with no
        # blank line between them, and without this second condition every
        # def after the first would be swallowed into the first one's body.
        while i < n and lines[i].strip() != "" and not _FOOTNOTE_DEF_START_RE.match(lines[i]):
            body.append(lines[i])
            i += 1
        defs[fid] = "\n".join(body)
    return defs


def _author_tokens(sources: list) -> set:
    """Normalized author-name tokens (surname/given-name pieces, len>=2)
    drawn from sources.json's `author` field -- the ONLY positive signal
    used to call a citation 'secondary' (per the subcommand spec: 'Use
    sources.json to classify'). Conservative by construction: a citation
    this can't positively match stays PRIMARY, never SECONDARY.
    """
    tokens: set = set()
    for src in sources:
        if not isinstance(src, dict):
            continue
        author = src.get("author")
        if not isinstance(author, str) or not author.strip():
            continue
        for part in re.split(r"[,\s]+", _nfc(author) or ""):
            part = part.strip()
            if len(part) >= 2:
                tokens.add(part)
    return tokens


def _contains_known_author(snippet: str, author_tokens: set) -> bool:
    return any(tok in snippet for tok in author_tokens)


def classify_citations(article_text: str, sources: list, citation_guard_module) -> dict:
    """Count and classify citation occurrences in `article_text`.

    Span detection REUSES citation-guard.py's `FOOTNOTE_RE` (footnote
    marker spans) and `PAREN_CITATION_RE` (parenthetical author/year or
    page-locator citation spans) verbatim -- see
    `change_overlaps_guard_token()` in citation-guard.py, where these same
    two patterns (plus TALMUD_FOLIO_RE/BOOK_CHAPTER_VERSE_RE/quote
    patterns, not needed here) form its citation-token set.

    Classification (secondary vs primary) is this function's own logic:
    a footnote marker is classified by whether ITS definition body
    contains a known sources.json author token; a parenthetical citation
    is classified by whether the parenthetical text itself does. Each
    footnote id is counted once, at its first reference (a citation
    reused three times in prose is one source, not three).
    """
    footnote_defs = _extract_footnote_defs(article_text)
    author_tokens = _author_tokens(sources)
    secondary = 0
    primary = 0
    seen_footnote_ids: set = set()

    for line in article_text.splitlines():
        if _FOOTNOTE_DEF_START_RE.match(line):
            continue  # definition line itself is not a citation occurrence

        for m in citation_guard_module.FOOTNOTE_RE.finditer(line):
            fid_match = re.match(r"\[\^([^\]]+)\]", m.group(0))
            if not fid_match:
                continue
            fid = fid_match.group(1)
            if fid in seen_footnote_ids:
                continue
            seen_footnote_ids.add(fid)
            body = _nfc(footnote_defs.get(fid, "")) or ""
            if body and _contains_known_author(body, author_tokens):
                secondary += 1
            else:
                primary += 1

        for m in citation_guard_module.PAREN_CITATION_RE.finditer(line):
            snippet = _nfc(m.group(0)) or ""
            if _contains_known_author(snippet, author_tokens):
                secondary += 1
            else:
                primary += 1

    return {"secondary": secondary, "primary": primary}


def cmd_citation_floor(args) -> tuple[int, dict]:
    try:
        article_text = Path(args.article).read_text(encoding="utf-8")
    except OSError as exc:
        return 2, _make_result("citation-floor", "error", f"cannot read --article: {exc}", [])

    sources_data, err = _read_json_file(args.sources)
    if err:
        return 2, _make_result("citation-floor", "error", err, [])
    if not isinstance(sources_data, list):
        return 2, _make_result("citation-floor", "error", "--sources JSON must be an array", [])

    thresholds, err = _read_json_file(args.thresholds)
    if err:
        return 2, _make_result("citation-floor", "error", f"cannot read --thresholds: {err}", [])

    floor_cfg = thresholds.get("citationFloor") if isinstance(thresholds, dict) else None
    if floor_cfg is None and str(args.thresholds) != str(DEFAULT_THRESHOLDS_PATH):
        # citationFloor shipped after some projects' .academic-helper/thresholds.json was
        # generated -- that file carries every other key but not this one. Exiting 2 here
        # means the floor is inert, and silently so, on exactly the projects whose citation
        # habits are already formed (VER-18's whole point). Fall back to the plugin's own
        # shipped default, loudly -- never invent a number, and never stay quiet about it.
        default_thresholds, default_err = _read_json_file(str(DEFAULT_THRESHOLDS_PATH))
        if not default_err and isinstance(default_thresholds, dict):
            fallback_floor = default_thresholds.get("citationFloor")
            if fallback_floor is not None:
                floor_cfg = fallback_floor
                print(
                    f"WARNING: {args.thresholds} has no citationFloor config -- "
                    f"falling back to the plugin's shipped default at {DEFAULT_THRESHOLDS_PATH}. "
                    "Add citationFloor to the project's own thresholds.json to silence this "
                    "and to review whether the shipped default is the value you want enforced.",
                    file=sys.stderr,
                )

    try:
        min_rate = float(floor_cfg["minSecondaryPer1000Words"])
        min_total = int(floor_cfg["minSecondaryTotal"])
    except (KeyError, TypeError, ValueError) as exc:
        return 2, _make_result(
            "citation-floor", "error",
            f"thresholds.json missing citationFloor config (checked {args.thresholds} and the "
            f"plugin default {DEFAULT_THRESHOLDS_PATH}): {exc}",
            [],
        )

    try:
        citation_guard_module = _load_citation_guard()
    except ImportError as exc:
        return 2, _make_result("citation-floor", "error", str(exc), [])

    counts = classify_citations(article_text, sources_data, citation_guard_module)
    secondary = counts["secondary"]
    word_count = len(article_text.split())
    rate_floor = min_rate * (word_count / 1000.0)

    violations = []
    if secondary < rate_floor:
        violations.append(
            {
                "check": "rate-floor",
                "nodeId": "article",
                "detail": (
                    f"secondary citations {secondary} below rate floor "
                    f"{rate_floor:.2f} ({min_rate}/1000 words over {word_count} words)"
                ),
            }
        )
    if secondary < min_total:
        violations.append(
            {
                "check": "absolute-floor",
                "nodeId": "article",
                "detail": f"secondary citations {secondary} below absolute floor {min_total}",
            }
        )

    detail = f"secondary={secondary} primary={counts['primary']} words={word_count}"
    if violations:
        return 1, _make_result("citation-floor", "fail", detail, violations)
    return 0, _make_result("citation-floor", "pass", detail, [])


# --- subcommand: changes-schema ----------------------------------------------


def _json_path_from_error(error) -> str:
    json_path = getattr(error, "json_path", None)
    if isinstance(json_path, str) and json_path:
        return json_path
    parts = []
    for p in error.path:
        parts.append(f"[{p}]" if isinstance(p, int) else f".{p}")
    return "$" + "".join(parts) if parts else "$"


def cmd_changes_schema(args) -> tuple[int, dict]:
    data, err = _read_json_file(args.changes)
    if err:
        return 2, _make_result("changes-schema", "error", err, [])

    try:
        from jsonschema import Draft202012Validator
    except ImportError as exc:
        return 2, _make_result(
            "changes-schema", "error", f"jsonschema package not importable: {exc}", []
        )

    schema, err = _read_json_file(CHANGES_SCHEMA_PATH)
    if err:
        return 2, _make_result("changes-schema", "error", f"cannot read canonical schema: {err}", [])

    validator = Draft202012Validator(schema)
    errors = sorted(validator.iter_errors(data), key=lambda e: list(e.path))
    if errors:
        violations = [
            {"check": "schema", "path": _json_path_from_error(e), "detail": e.message} for e in errors
        ]
        return 1, _make_result(
            "changes-schema", "fail", f"{len(violations)} schema violation(s)", violations
        )
    return 0, _make_result("changes-schema", "pass", "changes payload matches schema", [])


def cmd_stale_evidence_ownership(args) -> tuple[int, dict]:
    """Require evidence ownership to identify the exact outline it describes."""
    outline_path = Path(args.outline)
    ownership_path = Path(args.evidence_ownership)
    if not outline_path.exists():
        return 2, _make_result("stale-evidence-ownership", "error", f"outline not found: {outline_path}", [])
    if not ownership_path.exists():
        return 0, _make_result("stale-evidence-ownership", "pass", f"{ownership_path} does not exist yet", [])
    try:
        ownership = json.loads(ownership_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return 2, _make_result("stale-evidence-ownership", "error", f"cannot read evidence ownership: {exc}", [])
    expected = hashlib.sha256(outline_path.read_bytes()).hexdigest()
    actual = ownership.get("outlineSha256") if isinstance(ownership, dict) else None
    if actual != expected:
        return 1, _make_result(
            "stale-evidence-ownership", "fail",
            f"{ownership_path} outlineSha256 does not match {outline_path}",
            [{"check": "stale-hash", "path": str(ownership_path), "detail": "outline hash mismatch"}],
        )
    return 0, _make_result("stale-evidence-ownership", "pass", f"{ownership_path} matches {outline_path}", [])


def cmd_outline_v2(args) -> tuple[int, dict]:
    """Validate the co-authored W2 outline against author intent and evidence."""
    outline, err = _read_json_file(args.outline)
    if err:
        return 2, _make_result("outline-v2", "error", err, [])
    intent, err = _read_json_file(args.intent)
    if err:
        return 2, _make_result("outline-v2", "error", err, [])
    evidence, err = _read_json_file(args.evidence)
    if err:
        return 2, _make_result("outline-v2", "error", err, [])
    if not all(isinstance(value, dict) for value in (outline, intent, evidence)):
        return 2, _make_result("outline-v2", "error", "outline, intent, and evidence must be JSON objects", [])

    try:
        from jsonschema import Draft202012Validator
    except ImportError as exc:
        return 2, _make_result("outline-v2", "error", f"jsonschema package not importable: {exc}", [])
    schema_violations = []
    for artifact, schema_path, artifact_name in (
        (intent, AUTHOR_INTENT_SCHEMA_PATH, "intent"),
        (outline, OUTLINE_V2_SCHEMA_PATH, "outline"),
    ):
        schema, schema_error = _read_json_file(schema_path)
        if schema_error:
            return 2, _make_result("outline-v2", "error", f"cannot read {artifact_name} schema: {schema_error}", [])
        errors = sorted(Draft202012Validator(schema).iter_errors(artifact), key=lambda item: list(item.path))
        schema_violations.extend(
            {"check": f"{artifact_name}-schema", "path": _json_path_from_error(error), "detail": error.message}
            for error in errors
        )
    if schema_violations:
        return 1, _make_result("outline-v2", "fail", f"{len(schema_violations)} schema violation(s)", schema_violations)

    sections = outline.get("sections")
    intent_thesis = intent.get("thesis")
    outline_thesis = outline.get("thesis")
    if not isinstance(sections, list) or not isinstance(intent_thesis, str) or not isinstance(outline_thesis, str):
        return 2, _make_result("outline-v2", "error", "invalid outline or intent structure", [])

    violations = []
    expected_hash = hashlib.sha256(intent_thesis.encode("utf-8")).hexdigest()
    if outline.get("thesisSha256") != expected_hash:
        violations.append({"check": "thesis-drift", "detail": "thesisSha256 does not match intent.thesis"})
    if outline_thesis != intent_thesis:
        violations.append({"check": "thesis-drift", "detail": "outline thesis differs from author intent"})

    passages = evidence.get("passages")
    passage_ids = {item.get("id") for item in passages if isinstance(item, dict) and isinstance(item.get("id"), str)} if isinstance(passages, list) else set()
    placed = set()
    ids = set()
    graph = {}
    for section in sections:
        if not isinstance(section, dict):
            return 2, _make_result("outline-v2", "error", "each section must be an object", [])
        sid = section.get("id")
        if isinstance(sid, str):
            ids.add(sid)
            graph.setdefault(sid, [])
        if section.get("approved") is not True:
            violations.append({"check": "unapproved-section", "sectionId": sid, "detail": "section claim is not approved"})
        units = section.get("units", [])
        if not isinstance(units, list):
            return 2, _make_result("outline-v2", "error", "section units must be an array", [])
        for unit in units:
            if not isinstance(unit, dict):
                return 2, _make_result("outline-v2", "error", "each unit must be an object", [])
            uid = unit.get("id")
            if isinstance(uid, str):
                ids.add(uid)
                graph.setdefault(uid, [])
            dependencies = unit.get("dependsOn", [])
            if not isinstance(dependencies, list):
                return 2, _make_result("outline-v2", "error", "unit dependsOn must be an array", [])
            if isinstance(uid, str):
                graph[uid] = [dep for dep in dependencies if isinstance(dep, str)]
            paragraphs = unit.get("paragraphs", [])
            if not isinstance(paragraphs, list):
                return 2, _make_result("outline-v2", "error", "unit paragraphs must be an array", [])
            for paragraph in paragraphs:
                if not isinstance(paragraph, dict) or not isinstance(paragraph.get("evidenceIds", []), list):
                    return 2, _make_result("outline-v2", "error", "paragraph evidenceIds must be an array", [])
                for evidence_id in paragraph.get("evidenceIds", []):
                    if not isinstance(evidence_id, str) or evidence_id not in passage_ids:
                        violations.append({"check": "unresolved-evidence", "evidenceId": evidence_id, "detail": "evidence id does not resolve against passages[].id"})
                    else:
                        placed.add(evidence_id)

    for passage_id in intent.get("mustUse", []):
        if passage_id not in placed:
            violations.append({"check": "must-use-unplaced", "passageId": passage_id, "detail": "required passage is not placed in a paragraph"})

    # Only dependencies on known units form graph edges; dangling references are
    # schema/content errors for a later gate, while this gate's contract is cycles.
    state = {}
    cycle_nodes = set()
    def visit(node):
        if state.get(node) == 1:
            cycle_nodes.add(node)
            return
        if state.get(node) == 2:
            return
        state[node] = 1
        for dependency in graph.get(node, []):
            if dependency in ids:
                if state.get(dependency) == 1:
                    cycle_nodes.update((node, dependency))
                else:
                    visit(dependency)
                    if dependency in cycle_nodes:
                        cycle_nodes.add(node)
        state[node] = 2
    for node in graph:
        visit(node)
    if cycle_nodes:
        violations.append({"check": "dependency-cycle", "nodeIds": sorted(cycle_nodes), "detail": "dependsOn contains a cycle"})

    if violations:
        return 1, _make_result("outline-v2", "fail", f"{len(violations)} outline violation(s)", violations)
    return 0, _make_result("outline-v2", "pass", "outline matches author intent and evidence", [])


# --- CLI ----------------------------------------------------------------------

GATE_HANDLERS = {
    "argument-graph": cmd_argument_graph,
    "coverage": cmd_coverage,
    "citation-floor": cmd_citation_floor,
    "changes-schema": cmd_changes_schema,
    "stale-evidence-ownership": cmd_stale_evidence_ownership,
    "outline-v2": cmd_outline_v2,
}


def build_arg_parser() -> argparse.ArgumentParser:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument(
        "--ledger",
        default=None,
        help="Path to session-state.json. Default: $CLAUDE_PROJECT_DIR/.academic-helper/"
        "session-state.json, else ./.academic-helper/session-state.json.",
    )
    common.add_argument(
        "--thresholds",
        default=str(DEFAULT_THRESHOLDS_PATH),
        help="Path to thresholds.json (default: src/thresholds.json).",
    )
    common.add_argument("--json", action="store_true", help="Emit a single JSON verdict object to stdout.")

    parser = argparse.ArgumentParser(
        prog="gate.py",
        description="Deterministic quality-gate dispatcher (ACI-03 exit codes: "
        "0=pass, 1=fail, 2=could not run).",
    )
    subparsers = parser.add_subparsers(dest="subcommand", required=True)

    p_ag = subparsers.add_parser(
        "argument-graph", parents=[common], help="Validate an outline's argument graph."
    )
    p_ag.add_argument("outline", help="Path to outline.json")

    p_cov = subparsers.add_parser(
        "coverage", parents=[common], help="Validate a deep-read payload's chapter_coverage."
    )
    p_cov.add_argument("deep_read", help="Path to deep-read.json")

    p_cf = subparsers.add_parser(
        "citation-floor", parents=[common], help="Enforce the secondary-citation floor (VER-18)."
    )
    p_cf.add_argument("article", help="Path to article.md")
    p_cf.add_argument("--sources", required=True, help="Path to sources.json")

    p_cs = subparsers.add_parser(
        "changes-schema", parents=[common], help="Validate a changes.json payload against the canonical schema."
    )
    p_cs.add_argument("changes", help="Path to changes.json")

    p_seo = subparsers.add_parser(
        "stale-evidence-ownership", parents=[common],
        help="Refuse an evidence-ownership.json older than the current outline.json.",
    )
    p_seo.add_argument("outline", help="Path to outline.json")
    p_seo.add_argument("--evidence-ownership", required=True, help="Path to evidence-ownership.json")

    p_ov2 = subparsers.add_parser("outline-v2", parents=[common], help="Validate an author-approved outline against intent and evidence.")
    p_ov2.add_argument("--outline", required=True, help="Path to outline.json")
    p_ov2.add_argument("--intent", required=True, help="Path to author-intent.json")
    p_ov2.add_argument("--evidence", required=True, help="Path to evidence.json")

    return parser


def main(argv: Optional[list] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)  # argparse itself exits 2 on bad args -- matches ACI-03

    handler = GATE_HANDLERS[args.subcommand]
    exit_code, result = handler(args)

    ledger_path = resolve_ledger_path(args.ledger)
    merge_ledger(ledger_path, args.subcommand, result)

    _print_result(result, args.json)
    return exit_code


if __name__ == "__main__":
    sys.exit(main())
